package com.supportsphere.dao; import com.supportsphere.model.*; import com.supportsphere.util.*; import java.sql.*; import java.util.*; public class FeedbackDAO { public void save(Feedback f)throws Exception{try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false);try{try(PreparedStatement p=c.prepareStatement("INSERT INTO feedback(request_id,requester_id,volunteer_id,rating,comment) VALUES(?,?,?,?,?)")){p.setInt(1,f.requestId());p.setInt(2,f.requesterId());p.setInt(3,f.volunteerId());p.setInt(4,f.rating());p.setString(5,f.comment());p.executeUpdate();}try(PreparedStatement p=c.prepareStatement("UPDATE volunteer_profiles SET rating=((rating*rating_count)+?)/(rating_count+1),rating_count=rating_count+1 WHERE volunteer_id=?")){p.setInt(1,f.rating());p.setInt(2,f.volunteerId());if(p.executeUpdate()!=1)throw new SQLException("Volunteer profile not found.");}try(PreparedStatement p=c.prepareStatement("INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,'FEEDBACK')")){p.setInt(1,f.volunteerId());p.setString(2,"New feedback received");p.setString(3,"You received a "+f.rating()+"-star review for request #"+f.requestId()+".");p.executeUpdate();}c.commit();}catch(Exception e){c.rollback();throw e;}}} public boolean exists(int requestId)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT 1 FROM feedback WHERE request_id=?")){p.setInt(1,requestId);try(ResultSet r=p.executeQuery()){return r.next();}}} }
